cart.scss:
@import "global-objects";

#main-content {
  > .container {
    max-width: 100%;
    width: 100%;
    margin: 0;
    padding: 0;
  }
}

.twelve-cart {
  color: var(--ink);
  font-family: var(--serif);
  margin-left: auto;
  margin-right: auto;
  max-width: 1512px;
  padding: 0 56px 128px;
  &__inner {
    margin: 0 auto;
    padding: 0;
    max-width: none;
  }
  .breadcrumbs {
    margin: 0 0 20px;
    text-align: left;
  }
  &__header {
    align-items: flex-end;
    border-bottom: 1px solid var(--black);
    display: flex;
    gap: 32px;
    justify-content: space-between;
    padding-bottom: 24px;
    h1 {
      font-family: var(--sans);
      font-size: clamp(44px, 4vw, 60px);
      font-weight: 300;
      letter-spacing: 0;
      line-height: 1.04;
      margin: 14px 0 0;
      white-space: nowrap;
    }
    p {
      color: #000000;
      font-size: 14px;
      line-height: 1.45;
      margin: 0 0 3px;
      max-width: 560px;
      text-align: right;
    }
  }
  &__layout {
    align-items: start;
    display: grid;
    gap: 64px;
    grid-template-columns: minmax(0, 1.65fr) minmax(300px, 0.95fr);
    padding-top: 48px;
  }
  &__aside {
    display: grid;
    gap: 24px;
    position: sticky;
    top: 120px;
  }
  &__summary {
    border: 1px solid var(--black);
    padding: 28px 24px;
  }
  &__summary > .twelve-eyebrow {
    margin: 0;
  }
  &__summary-list {
    display: grid;
    gap: 12px 24px;
    grid-template-columns: 1fr auto;
    margin: 24px 0;
    dt,
    dd {
      font-size: 15px;
      margin: 0;
    }
    dd {
      font-family: var(--sans);
      font-variant-numeric: tabular-nums;
      text-align: right;
    }
    dt:last-of-type,
    dd:last-of-type {
      border-top: 1px solid var(--hair);
      font-weight: 500;
      padding-top: 14px;
    }
  }
  &__fineprint {
    color: #000000;
    font-size: 14.5px;
    line-height: 1.45;
    margin: 0 0 24px;
    letter-spacing: 0.1px;
  }
  &__fineprint--last {
    margin: 16px 0 0;
  }
  &__guidance {
    color: #8b1e32;
    font-size: 16px;
    font-weight: 500;
    line-height: 1.45;
    margin: 18px 0 0;
  }
  &__notice {
    border: 1px solid var(--black);
    margin-bottom: 16px;
    padding: 16px;
    p {
      color: var(--ink-52);
      font-size: 14px;
      line-height: 1.45;
      margin: 7px 0 0;
    }
  }
  &__text-link,
  &__info-card a {
    align-items: center;
    background-image: linear-gradient(var(--black), var(--black));
    background-position: 0 100%;
    background-repeat: no-repeat;
    background-size: 100% 1px;
    color: var(--ink);
    display: inline-flex;
    font-family: var(--sans-ext);
    font-size: 11px;
    font-weight: 500;
    letter-spacing: 0.025em;
    margin-top: 16px;
    padding-bottom: 5px;
    text-transform: uppercase;
    transition: background-size 0.42s var(--ease);
    span {
      display: inline-block;
      margin-left: 8px;
      transition: transform 0.42s var(--ease);
    }
  }
  &__text-link:hover,
  &__info-card a:hover {
    background-size: 0% 1px;
    color: var(--ink);
  }
  &__text-link:hover span,
  &__info-card a:hover span {
    transform: translateX(5px);
  }
  &__info-card {
    border: 1px solid var(--hair-strong);
    padding: 28px 24px;
    p {
      color: var(--ink-72);
      font-size: 14px;
      line-height: 1.45;
      margin: 8px 0 0;
    }
    dl {
      display: grid;
      gap: 8px 20px;
      grid-template-columns: 1fr auto;
      margin: 18px 0 0;
    }
    dt {
      color: var(--ink-72);
      font-family: var(--sans-ext);
      font-size: 10px;
      letter-spacing: 0.025em;
      text-transform: uppercase;
    }
    dd {
      font-size: 13px;
      margin: 0;
    }
  }
  &__customization-card {
    h2,
    h3 {
      font-family: var(--sans-ext);
      font-weight: 500;
      letter-spacing: 0.025em;
      text-transform: uppercase;
    }
    h2 {
      font-size: 16px;
      line-height: 1.2;
      margin: 0;
      color: #000000;
    }
    .twelve-cart__customization-intro {
      color: var(--ink);
      font-family: var(--serif);
      font-size: 17px;
      line-height: 1.35;
      margin-top: 10px;
    }
    .twelve-cart__customization-next-steps {
      border-top: 1px solid var(--hair);
      margin-top: 16px;
      padding-top: 16px;
      h3 {
        color: var(--ink-72);
        font-size: 14px;
        line-height: 1.2;
        margin: 0 0 8px;
      }
      p {
        color: var(--ink);
        font-family: var(--serif);
        font-size: 16px;
        line-height: 1.45;
        margin: 0;
      }
      .twelve-cart__customization-note {
        color: var(--ink-72);
        font-family: var(--sans);
        font-size: 15px;
        margin-top: 8px;
      }
    }
  }
  &__empty {
    border-bottom: 1px solid var(--hair);
    padding: 96px 0;
    text-align: center;
    h2 {
      font-family: var(--sans);
      font-size: 36px;
      font-weight: 300;
    }
    p {
      margin: 10px 0 24px;
    }
  }
  .twelve-cart-table__head,
  .twelve-cart-line {
    display: grid;
    gap: 16px;
    grid-template-columns: minmax(260px, 1fr) 116px 132px 92px;
  }
  .twelve-cart-table__head {
    border-bottom: 1px solid var(--hair);
    color: var(--ink-72);
    font-family: var(--sans-ext);
    font-size: 12px;
    font-weight: 500;
    letter-spacing: 0.025em;
    padding-bottom: 14px;
    text-transform: uppercase;
  }
  .twelve-cart-table__head span:last-child {
    text-align: right;
  }
  .twelve-cart-line {
    align-items: start;
    border-bottom: 1px solid var(--hair);
    padding: 24px 0;
  }
  .twelve-cart-line__product {
    display: grid;
    gap: 16px;
    grid-template-columns: 96px 1fr;
  }
  .twelve-cart-line__figure {
    border: 1px solid var(--hair);
    display: block;
    height: 96px;
    width: 96px;
  }
  .cart-item-image,
  .cart-item-fixed-image {
    height: 100%;
    object-fit: contain;
    width: 100%;
  }
  .twelve-cart-line h2 {
    font-family: var(--serif);
    font-size: 16px;
    font-weight: 400;
    line-height: 1.25;
    margin: 0;
  }
  .twelve-cart-line h2 a {
    background-image: linear-gradient(var(--black), var(--black));
    background-position: 0 100%;
    background-repeat: no-repeat;
    background-size: 0% 1px;
    color: var(--ink);
    padding-bottom: 2px;
    transition: background-size 0.3s var(--ease);
  }
  .twelve-cart-line h2 a:hover {
    background-size: 100% 1px;
    color: var(--ink);
  }
  .twelve-cart-line__meta {
    display: grid;
    gap: 3px;
    margin-top: 6px;
  }
  .twelve-cart-line__meta span,
  .twelve-cart-line__unit span,
  .twelve-cart-line__minimum {
    color: var(--ink-72);
    font-family: var(--sans-ext);
    font-size: 12px;
    letter-spacing: 0.025em;
    line-height: 1.35;
    text-transform: uppercase;
  }
  .twelve-cart-line .twelve-cart-line__remove {
    background: transparent;
    border: 0;
    border-bottom: 1px solid var(--hair-strong);
    border-radius: 0;
    display: inline-block;
    float: none;
    font:500 12px/1.3 var(--sans-ext);
    height: auto;
    letter-spacing: 0.025em;
    line-height: 1.2;
    margin: 11px 0 0;
    padding: 0 0 2px;
    position: static;
    color: inherit;
    text-transform: uppercase;
    transition:
      border-color 0.3s var(--ease),
      color 0.3s var(--ease);
    width: auto;
  }
  .twelve-cart-line .twelve-cart-line__remove:hover {
    background: transparent;
    border-bottom-color: var(--crimson);
    color: var(--crimson);
  }
  .twelve-cart-line__unit,
  .twelve-cart-line__total {
    font-family: var(--sans);
    font-size: 14px;
    font-variant-numeric: tabular-nums;
  }
  .twelve-cart-line__unit span {
    display: block;
    margin-top: 4px;
  }
  .twelve-cart-line__total {
    text-align: right;
  }
  .twelve-cart-line__quantity {
    display: grid;
    gap: 8px;
    justify-items: start;
  }
  .twelve-cart-line__quantity .form-increment {
    align-items: stretch;
    border: 1px solid var(--hair-strong);
    border-radius: 0;
    display: inline-flex;
    height: 36px;
    margin: 0;
    overflow: hidden;
  }
  .twelve-cart-line__quantity .form-increment .button {
    align-items: center;
    background: transparent;
    border: 0;
    border-radius: 0;
    box-shadow: none;
    color: var(--ink-72);
    display: flex;
    flex: 0 0 34px;
    font-size: 15px;
    height: 34px;
    justify-content: center;
    line-height: 1;
    margin: 0;
    min-width: 0;
    padding: 0;
    transform: none;
    transition:
      background-color 0.15s ease,
      color 0.15s ease;
    width: 34px;
  }
  .twelve-cart-line__quantity .form-increment .button:hover,
  .twelve-cart-line__quantity .form-increment .button:focus {
    background: var(--black);
    border: 0;
    box-shadow: none;
    color: var(--white);
    transform: none;
  }
  .cart-item-qty-input {
    border: 0;
    border-radius: 0;
    box-shadow: none;
    font-family: var(--sans);
    font-size: 13px;
    height: 34px;
    margin: 0;
    padding: 0;
    text-align: center;
    width: 38px;
  }
}
.twelve-cart.page {
  box-sizing: border-box;
  left: auto;
  margin-left: auto;
  margin-right: auto;
  margin-top: -22px;
  max-width: 1512px;
  padding: 0 56px 128px;
  position: static;
  transform: none;
  width: 100%;
}
.twelve-eyebrow {
  color: var(--ink);
  display: block;
  font-family: var(--sans-ext);
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.025em;
  line-height: 1.2;
  text-transform: uppercase;
}
.twelve-button {
  align-items: center;
  background: var(--black);
  border: 1px solid var(--black);
  color: var(--white);
  display: inline-flex;
  font-family: var(--sans-ext);
  font-size: 14px;
  font-weight: 500;
  justify-content: center;
  letter-spacing: 0.025em;
  min-height: 48px;
  overflow: hidden;
  padding: 17px 30px;
  position: relative;
  text-align: center;
  text-transform: uppercase;
  transition:
    color 0.42s var(--ease),
    border-color 0.42s var(--ease);
  z-index: 0;
}
.twelve-button::after {
  background: var(--white);
  content: "";
  inset: 0;
  position: absolute;
  transform: translateY(101%);
  transition: transform 0.42s var(--ease);
  z-index: -1;
}
.twelve-button:hover {
  color: var(--black);
}
.twelve-button:hover::after {
  transform: translateY(0);
}
.twelve-button--block {
  display: flex;
  width: 100%;
}
@media (min-width: 992px) and (max-width: 1200px) {
  .twelve-cart.page {
    padding-left: 32px;
    padding-right: 32px;
  }
}
@media (max-width: 991px) {
  .twelve-cart.page {
    padding-left: 16px;
    padding-right: 16px;
  }
  .twelve-cart {
    &__layout {
      grid-template-columns: 1fr;
    }
    &__aside {
      position: static;
    }
  }
}
@media (max-width: 767px) {
  .twelve-cart.page {
    left: auto;
    margin-left: auto;
    margin-right: auto;
    padding-bottom: 80px;
    padding-top: 24px;
    transform: none;
    width: 100%;
  }
  .twelve-cart {
    &__header {
      align-items: flex-start;
      flex-direction: column;
      gap: 14px;
      h1 {
        white-space: normal;
        font-size: 32px;
      }
      p {
        text-align: left;
      }
    }
    &__layout {
      gap: 40px;
      padding-top: 32px;
    }
    .twelve-cart-table__head {
      display: none;
    }
    .twelve-cart-line {
      grid-template-columns: 1fr;
      gap: 14px;
    }
    .twelve-cart-line__product {
      grid-template-columns: 76px 1fr;
    }
    .twelve-cart-line__figure {
      height: 76px;
      width: 76px;
    }
    .twelve-cart-line__total {
      text-align: left;
    }
  }
}
@media (max-width: 480px) {
  .twelve-cart.page {
    padding-left: 12px;
    padding-right: 12px;
  }
}

.twelve-cart__summary-list {
  dt {
    font-weight: normal;
    font-family: var(--serif);
    font-size: 15px;
    color: var(--ink-72);
  }
}

