assets/scss/user-authentication.scss:
@import "global-objects";

.alertBoxInfo{
    padding: 10px 50px 10px 16px;
    border-radius: 8px;
    border: 1px solid #707070;

    &.alertBoxInfo {
      padding: 10px 10px 10px 16px;
    }
    
    .alertBox-message, .alertBoxInfo-message{
        font-family: var(--sans-ext);
        font-size: 14px;
        font-weight: 400;
        line-height: 22px;
        text-align: left;
        color: #000000;
        margin: 0;
        span{
          width: 100%;
        }
    }
    
    .alertBox-column{
        vertical-align: text-top;
    }
    
    .icon {
        height: 18px;
        width: 20px;
        margin: -2px 0 0 0;
    }

    .alertBox-close{
        cursor: pointer;
        padding: 0;
        position: absolute;
        top: 0;
        width: 30px;
        height: 43px;
        right: 0;
        border-radius: 8px;
        svg{
            width: 22px;
            height: 22px;
            display: block;
            margin: 0 auto;
            fill: #838383 !important;
        }
        &:hover, &:focus {
            background-color:transparent !important;
            border-color: transparent;
        }
    }
    

  &.alertBoxInfo--info,
   &.alertBox--info{
       background: #E6F4FF;
       border-color:#91CAFF;
       svg{ fill: #000000; }
   }
   
   &.alertBoxInfo--success,
   &.alertBox--success{
       background: #F6FFED;
       border-color:#B7EB8F;
       svg{ fill: #52C41A; }
   }
   
   &.alertBoxInfo--warning,
   &.alertBox--warning{
       background:#FFFBE6;
       border-color: #FFE58F;
       svg{ fill:#FAAD14; }
   }
   
   &.alertBoxInfo--error,
   &.alertBox--error {
       background:#FFF1F0;
       border-color: #FFA39E;
       svg{ fill:#FF4D4F; }
   }
   
}

.bc-authentication-model {
    display: none;
    width: 100%;
    height: 100%;
    position: fixed;
    padding: 15px;
    left: 0;
    top: 0;
    z-index: 9999999999;
    background: rgba($color: #000000, $alpha: 0.5);
    align-items: center;
    justify-content: center;
    backdrop-filter: blur(7px);

    .alertBox{
        display: none;
        margin-top: 0 !important;
        .icon{
            display: none;
            margin: 0 !important;
            position: relative;
            top: 2px;
        }
    }

    .form-row {
        display: flex;
        @include md-phone{
            flex-wrap: wrap;
        }
    }

    .form-field{
        width: 100%;
        margin-bottom:10px;
        .form-label{
            font-size: 15px;
            color:#000000;
            small {
                float: left;
                font-size: 20px;
                color: #FF7875;
                padding-right: 5px;
                margin: 0;
            }
        }
        .form-select {
            color: #333333;
        }
        .form-input, .form-select {
            border-radius: 0;
            margin: 0;
            height: auto;
            padding: 10px;
            box-shadow: none;
            background-position: right center;
            color: #000;
            font-size: 15px;
        }
    }

    .form-actions{
        margin: 0;
        text-align: left;
        width: 100%;
        display: flex;
        align-items: center;
        flex-wrap: wrap;
    }
    
    .button{
        width: auto;
        margin: 0;
        padding: 10px 16px;
        border-radius: 6px;
        font-family: var(--sans-ext);
        font-size: 14px;
        line-height: 16px;
        font-weight: 400;
        text-align: left;
        text-transform: none;
        + .button{ 
            margin:0 0 0 15px;
        }
        
        &[disabled]{
            opacity: 0.6;
            pointer-events: none;
        }
    }
    
    .button--primary{
        background: #000000;
        border-color: #000000;
        color: #fff;
        &:hover{
            border-color: #000000;
            background: #ffffff;color:#000000;
        }
    }

    .buttonSecondary{
        border-color: #CCCCCC;
        + .buttonSecondary{
            margin-left: 15px;
        }
        &:hover{
            border-color: #CCCCCC;
            color: #000000;
        }
    }

    .view-password-action {
        position: relative;
        .view-password-icon{
            position: absolute;
            right: 5px;
            width: 30px;
            height: 30px;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            top: 5px;
            &:hover, &.is-active{
                svg{
                    path{
                        fill: #000000;
                    }
                }
            }
        }
    }

    /* Change the white to any color */
    input:-webkit-autofill,
    input:-webkit-autofill:hover, 
    input:-webkit-autofill:focus, 
    input:-webkit-autofill:active{
        -webkit-box-shadow: 0 0 0 30px #fff inset !important;
